#!/bin/sh
# First start of the bundle's database: the application role (no
# BYPASSRLS: row-level security backs every tenant predicate). Its password
# is generated by the gateway (hex, so it needs no quoting). The timescaledb
# extension (hypertables) is created in POSTGRES_DB by the image itself.
set -eu
psql -v ON_ERROR_STOP=1 --username postgres --dbname paperless <<SQL
CREATE ROLE paperless_app LOGIN PASSWORD '${PAPERLESS_APP_PASSWORD}' NOBYPASSRLS;
GRANT CONNECT ON DATABASE paperless TO paperless_app;
SQL
